WITH exploded AS (SELECT id, service, log_ts, level, latency_ms, status_code, k, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS k, attr_value) SELECT service, level, k, ROUND(status_code / SUM(status_code) OVER (PARTITION BY k, service), 4) status_code_share, MAX(status_code) OVER (ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) status_code_max_1h, SUM(status_code) OVER (PARTITION BY service) service_sum_status_code, CUME_DIST() OVER (PARTITION BY level ORDER BY latency_ms) latency_ms_cume_dist FROM exploded
